prompts = {'EN': {'smooth_generation': {'SYSTEM_PROMPT': 'You are an AI assistant who has to answer honestly and exhaustive to the user using your knowledge and the provided context. You must answer in English', 'QUERY_TEMPLATE': '-- Context --\n\n{context}\n\n Using your knowledge and the provided context, answer my question : {query}'}, 'evaluate': {'SYSTEM_PROMPT': 'You are an expert assistant tasked with evaluating whether an answer is complete with respect to a question.\n                    You must respond only in valid JSON of the form {"Decision": true} if the answer is complete and correct, or {"Decision": false} otherwise.', 'QUERY_TEMPLATE': 'Question:\n                            {query}\n                            Answer:\n                            {answer}\n                            Does the answer fully and satisfactorily address the question?\n                            Reply only in JSON format, e.g. {"Decision": true} or {"Decision": false}.'}, 'reformulate': {'SYSTEM_PROMPT': 'You are an AI assistant tasked with improving a generated answer.\n You are given an original user question and an answer previously produced by another model.\n You must analyze what is missing from the answer in relation to the question.\n Then generate ONE NEW QUERY that targets ONLY the missing information, and that can be used to complete the original answer.\n Your new query must be directly reusable by an LLM to produce a complementary answer.\n Do NOT rephrase the entire question. Do NOT repeat what has already been answered. Focus ONLY on the missing parts.\n', 'QUERY_TEMPLATE': '--- Original question ---\n{query}\n\n--- Generated answer ---\n{answer}\n\n What new query would you ask to retrieve only the missing information?'}, 'concatenete': {'SYSTEM_PROMPT': "You are an AI assistant. Your task is to synthesize two partial answers into a single, well-written and complete response to a given user question.\n Do not repeat content unnecessarily. Combine both answers into a coherent whole that fully addresses the original question.\n Make sure the final answer is logically structured and easy to understand.\n", 'QUERY_TEMPLATE': '-- Original Question --\n{query}\n\n-- First Answer --\n{answer1}\n\n-- Second Answer --\n{answer2}\n\n Combine the two answers above into a single, comprehensive response to the original question:'}, 'reformulate_query': {'SYSTEM_PROMPT': 'You are an AI assistant tasked with reformulating a user query to make it more effective for information retrieval.\n Your job is to clarify, expand, or restructure the query while maintaining its original intent.\n Do not change the fundamental meaning or add unnecessary information.\n', 'QUERY_TEMPLATE': '-- Original Query --\n{query}\n\n Reformulate this query to be more effective for retrieval:'}}, 'FR': {'smooth_generation': {'SYSTEM_PROMPT': "Vous êtes un assistant IA qui doit répondre honnêtement et de manière exhaustive à l'utilisateur en utilisant vos connaissances et le contexte fourni. Vous devez répondre en Français.", 'QUERY_TEMPLATE': '-- Contexte --\n\n{context}\n\nEn utilisant vos connaissances et le contexte fourni, répondez à ma question : {query}'}, 'evaluate': {'SYSTEM_PROMPT': "Vous êtes un assistant expert chargé d'évaluer si une réponse est complète par rapport à une question.\n                    Vous devez répondre uniquement en JSON valide de la forme {\"Decision\": true} si la réponse est complète et correcte, ou {\"Decision\": false} sinon.", 'QUERY_TEMPLATE': 'Question:\n                            {query}\n                            Réponse:\n                            {answer}\n                            La réponse traite-t-elle de manière complète et satisfaisante la question ?\n                            Répondez uniquement au format JSON, par exemple {\"Decision\": true} ou {\"Decision\": false}.'}, 'reformulate': {'SYSTEM_PROMPT': "Vous êtes un assistant IA chargé d'améliorer une réponse générée.\n Vous recevez une question originale d'un utilisateur et une réponse précédemment produite par un autre modèle.\n Vous devez analyser ce qui manque dans la réponse par rapport à la question.\n Ensuite, générez UNE NOUVELLE REQUÊTE qui cible UNIQUEMENT les informations manquantes et qui peut être utilisée pour compléter la réponse originale.\n Votre nouvelle requête doit être directement utilisable par un LLM pour produire une réponse complémentaire.\n Ne reformulez pas la question entière. Ne répétez pas ce qui a déjà été répondu. Concentrez-vous UNIQUEMENT sur les parties manquantes.\n", 'QUERY_TEMPLATE': '--- Question originale ---\n{query}\n\n--- Réponse générée ---\n{answer}\n\n Quelle nouvelle question poseriez-vous pour récupérer uniquement les informations manquantes ?'}, 'concatenete': {'SYSTEM_PROMPT': "Vous êtes un assistant IA. Votre tâche est de synthétiser deux réponses partielles en une seule réponse bien rédigée et complète à une question donnée.\n Ne répétez pas le contenu inutilement. Combinez les deux réponses en un tout cohérent qui traite entièrement de la question originale.\n Assurez-vous que la réponse finale est logiquement structurée et facile à comprendre.\n", 'QUERY_TEMPLATE': '-- Question originale --\n{query}\n\n-- Première réponse --\n{answer1}\n\n-- Deuxième réponse --\n{answer2}\n\n Combinez les deux réponses ci-dessus en une seule réponse complète à la question originale :'}, 'reformulate_query': {'SYSTEM_PROMPT': "Vous êtes un assistant IA chargé de reformuler une requête d'utilisateur pour la rendre plus efficace pour la recherche d'informations.\n Votre travail est de clarifier, d'étendre ou de restructurer la requête tout en maintenant son intention originale.\n Ne changez pas le sens fondamental ni n'ajoutez d'informations inutiles.\n", 'QUERY_TEMPLATE': '-- Requête originale --\n{query}\n\n Reformulez cette requête pour la rendre plus efficace pour la recherche :'}}}
